204	export function createPapercupsProjection(): PapercupsProjection {
205		const conversations: PapercupsConversation[] = PAPERCUPS_CONVERSATIONS.map((conversation) =>
206			structuredClone(conversation),
207		);
208		const replies: PapercupsMessage[] = [];
209		const byId = (id: string): PapercupsConversation | undefined =>
210			conversations.find((conversation) => conversation.id === id);
211		const filtered = (search: string): PapercupsConversation[] => {
212			const query = parseQuery(search);
213			const status = queryValue(query, 'status');
214			const priority = queryValue(query, 'priority');
215			const assignee = queryValue(query, 'assignee_id');
216			return conversations.filter(
217				(conversation) =>
218					(status === null || conversation.status === status) &&
219					(priority === null || conversation.priority === priority) &&
220					(assignee === null || `${conversation.assignee_id ?? ''}` === assignee),
221			);
222		};
223		const appendReply = (
224			conversationId: string,
225			body: string,
226			userId: number,
227		): PapercupsMessage | null => {
228			const conversation = byId(conversationId);
229			if (conversation === undefined || typeof body !== 'string' || body.trim().length === 0)
230				return null;
231			const reply: PapercupsMessage = {
232				body,
233				created_at: new Date(
234					REPLY_CLOCK_ORIGIN + replies.length * REPLY_CLOCK_STEP_MS,
235				).toISOString(),
236				conversation_id: conversationId,
237				account_id: PAPERCUPS_ACCOUNT.id,
238				user_id: userId,
239				user: { ...PAPERCUPS_USER },
240			};
241			conversation.messages.push(reply);
242			conversation.read = true;
243			replies.push(reply);
244			return reply;
245		};
246		const updateConversation = (id: string, body: Buffer): PapercupsApiResponse => {
247			const conversation = byId(id);
248			if (conversation === undefined) return failClosed(`/api/conversations/${id}`);
249			const updates = parsedBody(body).conversation;
250			if (updates !== undefined && (updates === null || typeof updates !== 'object'))
251				throw new Error('Papercups synthetic projection requires a conversation update object');
252			const requested = (updates ?? {}) as Partial<PapercupsConversation>;
253			if (requested.status === 'open' || requested.status === 'closed')
254				conversation.status = requested.status;
255			if (requested.priority === 'priority' || requested.priority === 'not_priority')
256				conversation.priority = requested.priority;
257			if (typeof requested.read === 'boolean') conversation.read = requested.read;
258			if (typeof requested.assignee_id === 'number' || requested.assignee_id === null)
259				conversation.assignee_id = requested.assignee_id;
260			return envelope(conversation);
261		};
262		const api = async (request: PapercupsApiRequest): Promise<PapercupsApiResponse | null> => {
263			if (!request.pathname.startsWith('/api/')) return null;
264			if (request.pathname === '/api/session')
265				return request.method === 'DELETE' ? json({ ok: true }) : envelope(PAPERCUPS_SESSION);
266			if (request.pathname === '/api/session/renew') return envelope(PAPERCUPS_SESSION);
267			if (request.pathname === '/api/me') return envelope(PAPERCUPS_USER);
268			if (request.pathname === '/api/accounts/me') return envelope(PAPERCUPS_ACCOUNT);
269			if (request.pathname === '/api/messages/count')
270				return envelope({
271					count: conversations.reduce(
272						(total, conversation) => total + conversation.messages.length,
273						0,
274					),
275				});
276			if (request.pathname === '/api/conversations')
277				return envelope(structuredClone(filtered(request.search)));
278			if (request.pathname.startsWith('/api/conversations/')) {
279				const id = request.pathname.slice('/api/conversations/'.length);
280				if (id.length === 0 || id.includes('/')) return failClosed(request.pathname);
281				if (request.method === 'GET') {
282					const conversation = byId(id);
283					return conversation === undefined
284						? failClosed(request.pathname)
285						: envelope(structuredClone(conversation));
286				}
287				return updateConversation(id, request.body);
288			}
289			return failClosed(request.pathname);
290		};
291		const channel: PhoenixChannelProjection = {
292			join: (topic) =>
293				topic === PAPERCUPS_NOTIFICATION_TOPIC || topic.startsWith('conversation:')
294					? { status: 'ok', response: {} }
295					: {
296							status: 'error',
297							response: { reason: `unsupported topic: ${topic}` },
298						},
299			event: (topic, event, payload): PhoenixChannelReply => {
300				if (event === 'shout') {
301					const conversationId = payload.conversation_id;
302					const body = payload.body;
303					const userId = payload.user_id;
304					const reply =
305						typeof conversationId === 'string' && typeof body === 'string'
306							? appendReply(
307									conversationId,
308									body,
309									typeof userId === 'number' ? userId : PAPERCUPS_USER.id,
310								)
311							: null;
312					return reply === null
313						? { status: 'error', response: { reason: 'unknown conversation' } }
314						: {
315								status: 'ok',
316								response: {},
317								broadcasts: [
318									{ event: 'shout', payload: { ...reply } as Record<string, unknown> },
319								],
320							};
321				}
322				if (event === 'read') {
323					const conversationId = payload.conversation_id;
324					const conversation =
325						typeof conversationId === 'string' ? byId(conversationId) : undefined;
326					if (conversation === undefined)
327						return { status: 'error', response: { reason: 'unknown conversation' } };
328					conversation.read = true;
329					return { status: 'ok', response: { conversation_id: conversation.id } };
330				}
331				if (event === 'watch:one' || event === 'watch:many')
332					return { status: 'ok', response: {} };
333				return { status: 'error', response: { reason: `unsupported event: ${topic} ${event}` } };
334			},
335		};
336		return {
337			api,
338			channel,
339			conversations: (search) => structuredClone(filtered(search)),
340			messages: (conversationId) => structuredClone(byId(conversationId)?.messages ?? []),
341			replies: () => structuredClone(replies),
342		};
343	}
