const MUTATION_CLOCK_ORIGIN_SECONDS = seconds('2026-08-09T00:00:00.000Z');
const MUTATION_CLOCK_STEP_SECONDS = 60;

const MEMO_TAG = createRegExp(
	exactly('#'),
	oneOrMore(char.notIn(' \n\t#')).groupedAs('tag'),
	exactly(' '),
